// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.IdentityHashMap;
import java.util.Map;

import org.junit.jupiter.api.Test;

/** Accounting of a detached planning copy that a cache freezes as its own retained template. */
class DetachedPlanningStateAccountingTest {
	private static final String DIAGNOSTIC = "optimizer.testDiagnostic";

	@Test
	void frozenCopyChargesItsDeferredDiagnosticForTheSnapshotAlone() {
		String text = "x".repeat(4_096);
		OwnedStringDiagnostic small = OwnedStringDiagnostic.builder().append("y").build();
		OwnedStringDiagnostic plain = OwnedStringDiagnostic.builder().append(text).build();
		OwnedStringDiagnostic json = OwnedStringDiagnostic.builder().jsonString(text).build();
		assertTrue(json.maximumRenderedCharacters() > 5L * plain.maximumRenderedCharacters());
		assertEquals(snapshot(plain), snapshot(json));

		long smallBytes = total(frozenCopyWith(small));
		long plainBytes = total(frozenCopyWith(plain));
		long jsonBytes = total(frozenCopyWith(json));

		assertEquals(plainBytes, jsonBytes, "a frozen copy never stores a rendering, so none is reserved");
		assertEquals(snapshot(plain) - snapshot(small), plainBytes - smallBytes,
				"only the diagnostic's data snapshot is charged");
	}

	@Test
	void frozenCopyRendersInPlaceWithoutRetainingTheRendering() {
		OwnedStringDiagnostic diagnostic = OwnedStringDiagnostic.builder()
				.append("owned:")
				.jsonString("\n".repeat(100))
				.build();
		SingletonSet frozen = frozenCopyWith(diagnostic);
		long before = total(frozen);

		String first = frozen.getStringMetricPlanned(DIAGNOSTIC);
		String second = frozen.getStringMetricPlanned(DIAGNOSTIC);
		assertEquals(diagnostic.get(), first);
		assertEquals(first, second);
		assertNotSame(first, second, "a frozen copy renders on every read and keeps no rendering");
		assertEquals(first, frozen.getStringMetricsPlanned().get(DIAGNOSTIC));
		assertEquals(before, total(frozen), "reading a frozen copy in place must not grow what it retains");

		// A copy taken from the frozen template is an ordinary plan again: it renders once and keeps the result.
		SingletonSet hit = new SingletonSet();
		assertTrue(frozen.copyDetachedPlanningStateTo(hit, (key, value, target) -> false));
		assertSame(hit.getStringMetricPlanned(DIAGNOSTIC), hit.getStringMetricPlanned(DIAGNOSTIC));
		assertEquals(diagnostic.get(), hit.getStringMetricPlanned(DIAGNOSTIC));
		assertEquals(before, total(frozen));
	}

	@Test
	void metricNamesAreNotCharged() {
		SingletonSet source = new SingletonSet();
		String dynamicName = new StringBuilder("optimizer.dynamic.").append(7).toString();
		source.setLongMetricPlanned("optimizer.constantLong", 5_000L);
		source.setDoubleMetricPlanned("optimizer.constantDouble", 2.5d);
		source.setStringMetricPlanned("optimizer.constantString", "constant-value");
		source.setStringMetricPlanned(dynamicName, "dynamic-value");

		IdentityHashMap<Object, Long> frozen = ledger(frozenCopy(source));
		assertFalse(frozen.containsKey("optimizer.constantLong"), "a class-constant name is retained by its class");
		assertFalse(frozen.containsKey("optimizer.constantDouble"));
		assertFalse(frozen.containsKey("optimizer.constantString"));
		assertEquals(40L + 2L * dynamicName.length(), frozen.get(dynamicName),
				"a name built at run time is retained by the copy and stays charged");

		IdentityHashMap<Object, Long> unfrozen = ledger(detachedCopy(source));
		assertTrue(unfrozen.containsKey("optimizer.constantLong"), "an unfrozen copy keeps its conservative charge");
		assertTrue(unfrozen.containsKey(dynamicName));
	}

	@Test
	void metricMapChargeMatchesLayoutModel() {
		for (int size : new int[] { 1, 2, 3, 6, 11, 12, 13, 24, 25, 48, 49, 96 }) {
			SingletonSet source = new SingletonSet();
			for (int i = 0; i < size; i++) {
				source.setLongMetricPlanned("m" + i, 1_000L + i);
				source.setDoubleMetricPlanned("d" + i, 0.5d + i);
			}
			SingletonSet frozenCopy = frozenCopy(source);
			IdentityHashMap<Object, Long> frozen = ledger(frozenCopy);
			Map<String, Long> longs = frozenCopy.getLongMetricsPlanned();
			Map<String, Double> doubles = frozenCopy.getDoubleMetricsPlanned();
			assertEquals(size, longs.size());
			assertEquals(layoutModel(size), frozen.get(longs), "long map, size=" + size);
			assertEquals(layoutModel(size), frozen.get(doubles), "double map, size=" + size);
			for (Long value : longs.values()) {
				assertEquals(24L, frozen.get(value), "a boxed Long is header plus 8 bytes, aligned");
			}
			for (Double value : doubles.values()) {
				assertEquals(24L, frozen.get(value), "a boxed Double is header plus 8 bytes, aligned");
			}

			SingletonSet unfrozenCopy = detachedCopy(source);
			assertEquals(192L + 96L * size, ledger(unfrozenCopy).get(unfrozenCopy.getLongMetricsPlanned()),
					"an unfrozen copy keeps its conservative map charge, size=" + size);
		}
	}

	/**
	 * The frozen HashMap model: the map object 64, its entry, key and value views 3 x 24, the table header 16 plus 8
	 * per slot for tableSizeFor(size * 4 / 3 + 1) slots, and 40 per node.
	 */
	private static long layoutModel(int size) {
		int requested = size * 4 / 3 + 1;
		long slots = requested == 1 ? 1 : Integer.highestOneBit(requested - 1) << 1;
		return 64L + 3L * 24L + 16L + 8L * slots + 40L * size;
	}

	private static SingletonSet frozenCopyWith(OwnedStringDiagnostic diagnostic) {
		SingletonSet source = new SingletonSet();
		source.setStringMetricPlannedDeferred(DIAGNOSTIC, diagnostic);
		return frozenCopy(source);
	}

	private static SingletonSet detachedCopy(SingletonSet source) {
		SingletonSet copy = new SingletonSet();
		assertTrue(source.copyDetachedPlanningStateTo(copy, (key, value, target) -> false));
		return copy;
	}

	private static SingletonSet frozenCopy(SingletonSet source) {
		SingletonSet copy = detachedCopy(source);
		assertTrue(copy.freezeDetachedPlanningState());
		return copy;
	}

	private static IdentityHashMap<Object, Long> ledger(QueryModelNode node) {
		IdentityHashMap<Object, Long> memory = new IdentityHashMap<>();
		assertTrue(node.accountDetachedPlanningState((object, bytes) -> memory.putIfAbsent(object, bytes) == null,
				(key, value, account) -> false));
		return memory;
	}

	private static long total(QueryModelNode node) {
		return ledger(node).values().stream().mapToLong(Long::longValue).sum();
	}

	private static long snapshot(OwnedStringDiagnostic diagnostic) {
		IdentityHashMap<Object, Long> memory = new IdentityHashMap<>();
		assertTrue(diagnostic.accountRetainedMemory((object, bytes) -> memory.putIfAbsent(object, bytes) == null));
		return memory.values().stream().mapToLong(Long::longValue).sum();
	}
}
